package ca.mcgill.ecse321.ecse321project03.repository;

import org.springframework.data.repository.CrudRepository;

import ca.mcgill.ecse321.ecse321project03.model.Item;

import java.util.List;

public interface ItemRepository extends CrudRepository<Item, Integer> {

    /**
     * Find items by name. Auto-generated by Spring Data JPA from method name.
     */
    List<Item> findByName(String name);

    /**
     * Find items by tag. Auto-generated by Spring Data JPA from method name.
     */
    List<Item> findByTag(Item.Tag tag);

    /**
     * Find items by price. Auto-generated by Spring Data JPA from method name.
     */
    List<Item> findByPrice(double price);
}
